#!/usr/bin/env python3
"""Browser regression for the shared workspace; pass the HTTP base URL."""
import subprocess, sys
base = sys.argv[1] if len(sys.argv) > 1 else 'http://127.0.0.1:8936/'
script = r"""
const {chromium}=require('playwright'); const fs=require('fs');const path=require('path');
(async()=>{const base=process.argv[1].replace(/\/?$/, '/');const dir=path.resolve('evidence/workspace-shell');fs.mkdirSync(dir,{recursive:true});const browser=await chromium.launch({headless:true,args:['--no-sandbox']});let errors=[], rows=[];
for(const width of [390,768,1440]){const ctx=await browser.newContext({viewport:{width,height:900}});const p=await ctx.newPage();p.on('pageerror',e=>errors.push(`${width}: ${e.message}`));p.on('console',m=>{if(m.type()==='error')errors.push(`${width}: console: ${m.text()}`)});
for(const url of ['studio.html','index.html?canvas=1','boards.html','assets.html','liquid.html']){await p.goto(base+url,{waitUntil:'domcontentloaded'});await p.waitForTimeout(1200);const r=await p.evaluate(()=>({shell:!!document.querySelector('.studio-shell__nav'),links:[...document.querySelectorAll('.studio-shell__nav a')].length,overflow:document.documentElement.scrollWidth-innerWidth,height:document.querySelector('.studio-shell').getBoundingClientRect().height,ready:document.body.dataset.ready,kit:!!window.DesignKit,requests:performance.getEntriesByType('resource').length,fonts:performance.getEntriesByType('resource').filter(x=>x.name.includes('fonts.googleapis')).length,duration:performance.getEntriesByType('navigation')[0].domContentLoadedEventEnd}));rows.push({width,url,...r});if(!r.shell||r.links!==6||!r.kit||r.overflow>0)errors.push(JSON.stringify({width,url,...r}));if(url.startsWith('index')||url.startsWith('boards')){if(r.ready!=='1')errors.push('not ready: '+url);const overlap=await p.evaluate(()=>{let a=document.querySelector('.studio-shell').getBoundingClientRect(),b=document.querySelector('.toolbar,.bar').getBoundingClientRect();return b.top<a.bottom-1});if(overlap)errors.push('shell overlap: '+width+' '+url);const zoom=await p.locator('#zVal').innerText();await p.locator('#zIn').click();await p.waitForTimeout(100);if((await p.locator('#zVal').innerText())===zoom)errors.push('zoom did not respond: '+url)}await p.screenshot({path:path.join(dir,`${width}-${url.split('?')[0]}.png`)});}
if(width===390){await p.goto(base+'index.html');await p.waitForURL('**/studio.html');}
await p.goto(base+'studio.html');await p.waitForSelector('[data-open]');let id=await p.locator('[data-open]').first().getAttribute('data-open');await p.locator('[data-fav]').first().click();await p.locator('[data-open]').first().click();await p.locator('#select-style').click();if(await p.evaluate(()=>DesignKit.get().styleId)!==id)errors.push('style not saved');await p.goto(base+'boards.html');await p.waitForTimeout(1200);if(!(await p.locator('.studio-shell__style').innerText()).includes(id))errors.push('style not shared');if(!(await p.evaluate(id=>DesignFavourites.read().has(id),id)))errors.push('favorite not shared');await p.goto(base+'assets.html');await p.waitForSelector('.kit-add');await p.locator('.kit-add').first().click();if(!(await p.evaluate(()=>DesignKit.get().assets.length)))errors.push('asset not saved');await p.locator('.studio-shell__search input').fill('brutal');await p.locator('.studio-shell__search button').click();await p.waitForURL('**/studio.html?q=brutal');if((await p.locator('#search').inputValue())!=='brutal')errors.push('search not shared');await ctx.close();}
fs.writeFileSync(path.join(dir,'results.json'),JSON.stringify({rows,errors},null,2));console.log(JSON.stringify({rows,errors},null,2));await browser.close();if(errors.length)process.exit(1)})().catch(e=>{console.error(e);process.exit(1)});
"""
raise SystemExit(subprocess.run(['node', '-e', script, base]).returncode)
